import java.util.*;

public class Main {
    enum OutboxStatus { NEW, SENT }
    enum TxState { COMMIT, ROLLBACK, UNKNOWN }

    static final class Order {
        final String id;
        final int quantity;
        Order(String id, int quantity) { this.id = id; this.quantity = quantity; }
    }

    static final class OutboxMessage {
        final String id;
        final String orderId;
        final int quantity;
        OutboxStatus status = OutboxStatus.NEW;
        int attempts;
        OutboxMessage(String id, String orderId, int quantity) {
            this.id = id;
            this.orderId = orderId;
            this.quantity = quantity;
        }
        OutboxMessage copy() { return new OutboxMessage(id, orderId, quantity); }
    }

    static final class Database {
        final Map<String, Order> orders = new LinkedHashMap<>();
        final List<OutboxMessage> outbox = new ArrayList<>();
        final Set<String> inbox = new LinkedHashSet<>();
        int stock = 10;
    }

    static final class OrderService {
        private final Database db;
        OrderService(Database db) { this.db = db; }
        void createOrder(String orderId, int quantity) {
            db.orders.put(orderId, new Order(orderId, quantity));
            db.outbox.add(new OutboxMessage("evt-" + orderId, orderId, quantity));
        }
    }

    static final class Broker {
        final Queue<OutboxMessage> queue = new ArrayDeque<>();
        int publishAttempts;
        void publish(OutboxMessage msg) {
            publishAttempts++;
            queue.add(msg.copy());
        }
    }

    static final class Relay {
        private final Database db;
        private final Broker broker;
        Relay(Database db, Broker broker) { this.db = db; this.broker = broker; }
        void publishOne(boolean crashAfterBrokerAck) {
            OutboxMessage msg = db.outbox.stream()
                    .filter(m -> m.status == OutboxStatus.NEW)
                    .findFirst()
                    .orElseThrow();
            msg.attempts++;
            broker.publish(msg);
            if (!crashAfterBrokerAck) {
                msg.status = OutboxStatus.SENT;
            }
        }
    }

    static final class InventoryConsumer {
        private final Database db;
        private final Broker broker;
        int duplicateSkipped;
        InventoryConsumer(Database db, Broker broker) { this.db = db; this.broker = broker; }
        void consumeAll() {
            while (!broker.queue.isEmpty()) {
                OutboxMessage msg = broker.queue.remove();
                if (!db.inbox.add(msg.id)) {
                    duplicateSkipped++;
                    continue;
                }
                db.stock -= msg.quantity;
            }
        }
    }

    static final class TxBroker {
        final Map<String, String> half = new LinkedHashMap<>();
        final List<String> visible = new ArrayList<>();
        void sendHalf(String txId, String payload) { half.put(txId, payload); }
        void commit(String txId) { visible.add(half.remove(txId)); }
        void rollback(String txId) { half.remove(txId); }
        void check(String txId, TxState state) {
            if (state == TxState.COMMIT) commit(txId);
            if (state == TxState.ROLLBACK) rollback(txId);
        }
    }

    public static void main(String[] args) {
        Database db = new Database();
        Broker broker = new Broker();
        new OrderService(db).createOrder("o1", 2);
        Relay relay = new Relay(db, broker);
        relay.publishOne(true);
        relay.publishOne(false);
        InventoryConsumer consumer = new InventoryConsumer(db, broker);
        consumer.consumeAll();

        OutboxMessage saved = db.outbox.get(0);
        assert broker.publishAttempts == 2;
        assert saved.status == OutboxStatus.SENT;
        assert db.stock == 8;
        assert consumer.duplicateSkipped == 1;

        TxBroker txBroker = new TxBroker();
        txBroker.sendHalf("tx-o2", "OrderCreated:o2");
        db.orders.put("o2", new Order("o2", 1));
        TxState checked = db.orders.containsKey("o2") ? TxState.COMMIT : TxState.ROLLBACK;
        txBroker.check("tx-o2", checked);
        assert txBroker.visible.equals(List.of("OrderCreated:o2"));
        assert txBroker.half.isEmpty();

        System.out.println("outbox sends=" + broker.publishAttempts
                + ", status=" + saved.status
                + ", stock=" + db.stock
                + ", duplicatesSkipped=" + consumer.duplicateSkipped);
        System.out.println("txMessage visible=" + txBroker.visible
                + ", remainingHalf=" + txBroker.half.size());
    }
}
